Пирамидальная сортировка / Heapsort O(n*logn)

Развитие идеи сортировки выбором. Воспользуемся структурой данных «куча» (или «пирамида», откуда и название алгоритма). Она позволяет получать минимум за O(1), добавляя элементы и извлекая минимум за O(logn). Таким образом, асимптотика O(n*logn) в худшем, среднем и лучшем случае.

public class HeapSort {

public static void main(String args[]) {

int[] testData = {8, 0, -3, 5, 6, 9, 8, -4, 2, -99, 43};

​

HeapSort ob = new HeapSort();

ob.sort(testData);

​

System.out.println("Sorted array is");

printArray(testData);

}

​

public void sort(int[] array) {

int n = array.length;

​

//Построение кучи (перегруппируем массив)

for (int i = n / 2 - 1; i >= 0; i--)

heapify(array, n, i);

​

//Один за другим извлекаем элементы из кучи

for (int i=n-1; i>=0; i--)

{

//Перемещаем текущий корень в конец

int temp = array[0];

array[0] = array[i];

array[i] = temp;

​

//Вызываем процедуру heapify на уменьшенной куче

heapify(array, i, 0);

}

}

​

//Процедура для преобразования в двоичную кучу поддерева с корневым узлом i, что является

//индексом в arr[]. n - размер кучи

void heapify(int[] arr, int n, int i) {

int largest = i; //Инициализируем наибольший элемент как корень

int l = 2*i + 1; //левый = 2*i + 1

int r = 2*i + 2; //правый = 2*i + 2

​

//Если левый дочерний элемент больше корня

if (l < n && arr[l] > arr[largest])

largest = l;

​

//Если правый дочерний элемент больше, чем самый большой элемент на данный момент

if (r < n && arr[r] > arr[largest])

largest = r;

//Если самый большой элемент не корень

if (largest != i) {

int swap = arr[i];

arr[i] = arr[largest];

arr[largest] = swap;

​

//Рекурсивно преобразуем в двоичную кучу затронутое поддерево

heapify(arr, n, largest);

}

}

​

/*Вспомогательная функция для вывода на экран массива размера n*/

static void printArray(int arr[]) {

int n = arr.length;

for (int i=0; i < n; ++i)

System.out.print(arr[i] + " ");

System.out.println();

}

}

